  @machines %{
    "admission.entrance" => %{
      "states" => ["idle", "arriving", "waiting", "admitted", "ended", "failed"],
      "edges" => [
        ["idle", "arriving"],
        ["failed", "arriving"],
        ["ended", "arriving"],
        ["arriving", "waiting"],
        ["arriving", "admitted"],
        ["arriving", "failed"],
        ["waiting", "admitted"],
        ["waiting", "failed"],
        ["waiting", "idle"],
        ["admitted", "failed"],
        ["admitted", "ended"]
      ],
      "triggers" => ["started", "rejoin_released", "waiting_for_host", "admitted", "call_ui_failed", "failed", "cancelled", "call_ended"]
    },
    "client.connection" => %{
      "states" => ["idle", "joining", "live", "reconnecting", "leaving", "left", "failed"],
      "edges" => [
        ["idle", "joining"],
        ["left", "joining"],
        ["failed", "joining"],
        ["joining", "live"],
        ["joining", "failed"],
        ["joining", "leaving"],
        ["live", "reconnecting"],
        ["reconnecting", "live"],
        ["live", "leaving"],
        ["reconnecting", "leaving"],
        ["failed", "leaving"],
        ["leaving", "left"],
        ["live", "failed"],
        ["reconnecting", "failed"]
      ],
      "triggers" => ["join", "joined", "join_failed", "leave", "left", "transport_lost", "recovered", "recovery_exhausted", "removed", "episode_ended"]
    },
    "episode.lifecycle" => %{
      "states" => ["active", "ending", "ended"],
      "edges" => [
        ["active", "ending"],
        ["ending", "ended"],
        ["active", "ended"]
      ],
      "triggers" => ["ended_by_participant", "tenant_recovery", "linger_expired", "maximum_duration"]
    },
    "prejoin.access" => %{
      "states" => ["checking", "ask", "requesting", "granted", "blocked"],
      "edges" => [
        ["checking", "ask"],
        ["checking", "granted"],
        ["checking", "blocked"],
        ["ask", "requesting"],
        ["requesting", "granted"],
        ["requesting", "blocked"],
        ["granted", "blocked"],
        ["blocked", "requesting"]
      ],
      "triggers" => ["permission_query", "device_labels", "preview_open", "request"]
    },
    "selftest.door" => %{
      "states" => ["closed", "open", "locked"],
